#include <string>
#include <algorithm>

class Solution {
public:
    int minFlipsToMakeCoherent(std::string s) {
        int n = s.length();
        int totalOnes = 0;
        for (char c : s) if (c == '1') totalOnes++;
        int totalZeros = n - totalOnes;
        int ans = std::min(totalOnes, totalZeros);
        if (totalOnes > 0) ans = std::min(ans, totalOnes - 1);
        if (n >= 2) {
            int cost = (s[0] == '1' ? 0 : 1) + (s[n - 1] == '1' ? 0 : 1);
            for (int i = 1; i < n - 1; ++i) {
                if (s[i] == '1') cost++;
            }
            ans = std::min(ans, cost);
        }
        return ans;
    }
};

class Solution {
    public int minFlipsToMakeCoherent(String s) {
        int n = s.length();
        int totalOnes = 0;
        for (int i = 0; i < n; i++) if (s.charAt(i) == '1') totalOnes++;
        int totalZeros = n - totalOnes;
        int ans = Math.min(totalOnes, totalZeros);
        if (totalOnes > 0) ans = Math.min(ans, totalOnes - 1);
        if (n >= 2) {
            int cost = (s.charAt(0) == '1' ? 0 : 1) + (s.charAt(n - 1) == '1' ? 0 : 1);
            for (int i = 1; i < n - 1; i++) {
                if (s.charAt(i) == '1') cost++;
            }
            ans = Math.min(ans, cost);
        }
        return ans;
    }
}

